import{_ as e,a as o,b as a}from"./chunks/8.Do7890Hz.js";import{_ as n}from"./chunks/2.BRgDBKom.js";import{_ as i,o as r,c as s,am as l}from"./chunks/framework.CenUaW7a.js";const c="/projects/AiMechaM1/en/advanced-kit/assets/1.BL9yqpIH.png",h="/projects/AiMechaM1/en/advanced-kit/assets/2.CuLc1zMY.png",d="/projects/AiMechaM1/en/advanced-kit/assets/4.LYNXAuRD.png",p="/projects/AiMechaM1/en/advanced-kit/assets/5.CmxtyF_i.png",g="/projects/AiMechaM1/en/advanced-kit/assets/7.D38vUOn8.png",m="/projects/AiMechaM1/en/advanced-kit/assets/9.DPLfhNBd.png",u="/projects/AiMechaM1/en/advanced-kit/assets/10.cEm0iQIu.png",f="/projects/AiMechaM1/en/advanced-kit/assets/11.CAgzGGfs.png",A=JSON.parse('{"title":"3.13 Lesson 13: Basic Manipulation Challenge","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.13 Lesson 13 Basic Manipulation Challenge.md","filePath":"docs/3. Course materials/3.13 Lesson 13 Basic Manipulation Challenge.md"}'),b={name:"docs/3. Course materials/3.13 Lesson 13 Basic Manipulation Challenge.md"};function v(w,t,y,_,x,k){return r(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="_3-13-lesson-13-basic-manipulation-challenge" tabindex="-1">3.13 Lesson 13: Basic Manipulation Challenge <a class="header-anchor" href="#_3-13-lesson-13-basic-manipulation-challenge" aria-label="Permalink to &quot;3.13 Lesson 13: Basic Manipulation Challenge&quot;">​</a></h1><h2 id="_3-13-1-lesson-introduction" tabindex="-1">3.13.1 Lesson Introduction <a class="header-anchor" href="#_3-13-1-lesson-introduction" aria-label="Permalink to &quot;3.13.1 Lesson Introduction&quot;">​</a></h2><p>Inspired by an &quot;elevator mechanism&quot;, this lesson introduces the complete hardware architecture of the Mecanum-wheel car, focusing on bus servo operation, robotic arm joint structure, and transmission mechanics. By programming the angular positions of the bus servos to raise and lower the arm, the project culminates in a hands-on task where the &quot;robotic arm cycles continuously between low and high positions&quot;. Through this process, the lesson provides a clear overview of the vehicle&#39;s hardware system and highlights the advantages of smart bus servos, laying a solid foundation for advanced manipulation tasks such as precision grasping and multi-level picking.</p><h2 id="_3-13-2-learning-objectives" tabindex="-1">3.13.2 Learning Objectives <a class="header-anchor" href="#_3-13-2-learning-objectives" aria-label="Permalink to &quot;3.13.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the complete hardware composition of the AiMecha M1 Mecanum-wheel car, including the functions and roles of the mecha controller, encoder motors, 6-channel line follower sensor, ultrasonic sensor, WonderLens vision module, and bus servos. Learn the functional roles of the three robotic arm joints and the concept of initial angles.</p><p><strong>2.</strong> Accurately identify each port on the mecha controller and complete the hardware wiring. Independently write programs to control the angular positions of bus servo ID 2 and bus servo ID 3, achieving forward extension, backward retraction, lifting, lowering, and cyclic low-to-high movements of the robotic arm.</p><p><strong>3.</strong> Build a &quot;Sense–Decide–Act&quot; robot control mindset and understand how the controller acts as the central &quot;brain&quot; for processing data and dispatching commands. Develop parameterized programming skills to precisely control robotic arm movements by tuning angular position parameters.</p><p><strong>4.</strong> Connect the lifting principle of the robotic arm to engineering equipment in daily life such as elevators, tower cranes, and hoists, understanding the practical value of vertical lifting modules in industrial scenarios.</p><h2 id="_3-13-3-preparation" tabindex="-1">3.13.3 Preparation <a class="header-anchor" href="#_3-13-3-preparation" aria-label="Permalink to &quot;3.13.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li><p>WonderLab graphical programming software</p></li><li><p>Loading Extensions: Click the Add Extension icon in the lower-left corner of the WonderLab interface, select &quot;Robot&quot; → &quot;AI Mecha Car&quot;, and then select &quot;Output Module&quot; → &quot;Bus Servo&quot;.</p></li></ul><h2 id="_3-13-4-hands-on-project" tabindex="-1">3.13.4 Hands-On Project <a class="header-anchor" href="#_3-13-4-hands-on-project" aria-label="Permalink to &quot;3.13.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This program focuses on the cyclic reciprocating motion of the robotic arm between low and high angles, following a closed-loop control logic of &quot;input → processing → output&quot;. After the program starts, bus servo ID 2 and bus servo ID 3 automatically return to their default power-on low positions. Pressing the A key triggers the controller to sequentially send motion commands with position parameters to both servos via serial communication. Servo ID 2 controls the forward extension and backward retraction of the robotic arm, while servo ID 3 controls the lifting and lowering of the robotic arm, working in coordination to switch postures from low to high. A loop structure then drives the robotic arm to reciprocate continuously between the low and high positions. After completing each action, each servo sends status feedback to the controller, which updates the system state before initiating the next command interaction, forming a stable serial closed-loop control system throughout the entire process.</p><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="111" width="662" src="'+c+'" class="common_img" style="width:300px;aspect-ratio:662 / 111;"></td><td style="text-align:left;">Powers on the bus servo with the specified ID to enter a controllable state and record rotational speed.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="115" width="660" src="'+h+'" class="common_img" style="width:300px;aspect-ratio:660 / 115;"></td><td style="text-align:left;">Powers off the bus servo with the specified ID, allowing manual adjustment of the robotic arm position.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="54" width="538" src="'+e+'" class="common_img" style="width:300px;aspect-ratio:538 / 54;"></td><td style="text-align:left;">Sets the servo to rotate to a specified angular position and defines the execution time in milliseconds.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="81" width="648" src="'+d+'" class="common_img" style="width:300px;aspect-ratio:648 / 81;"></td><td style="text-align:left;">Sets the servo to motor mode for continuous rotation at a specified speed.</td></tr><tr><td style="text-align:center;">Data acquisition</td><td style="text-align:center;"><img loading="lazy" height="99" width="725" src="'+p+'" class="common_img" style="width:300px;aspect-ratio:725 / 99;"></td><td style="text-align:left;">Reads the current angular position of the specified servo, typically used with variables.</td></tr><tr><td style="text-align:center;">Flow control</td><td style="text-align:center;"><img loading="lazy" height="157" width="515" src="'+o+'" class="common_img" style="width:160px;aspect-ratio:515 / 157;"></td><td style="text-align:left;">Pauses the program for a specified duration to maintain the state after a servo action completes.</td></tr><tr><td style="text-align:center;">Flow control</td><td style="text-align:center;"><img loading="lazy" height="284" width="413" src="'+g+'" class="common_img" style="width:140px;aspect-ratio:413 / 284;"></td><td style="text-align:left;">Loop structure that keeps the robotic arm lifting and lowering continuously.</td></tr><tr><td style="text-align:center;">Event trigger</td><td style="text-align:center;"><img loading="lazy" height="93" width="510" src="'+a+'" class="common_img" style="width:300px;aspect-ratio:510 / 93;"></td><td style="text-align:left;">Detects the A key press event on the controller to trigger the robotic arm action sequence.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Setting the Angular Position of Bus Servo ID 2 for Robotic Arm Extension and Retraction</strong></p><ul><li><p>Initialize the AI Mecha Car module and the bus servo module.</p></li><li><p>Power on bus servo ID 2.</p></li><li><p>When the A key is pressed, set the angular position of servo ID 2 to 100 for the retracted state with a running time of 2,000 ms.</p></li><li><p>Wait 5 s to observe the retraction process of the robotic arm.</p></li><li><p>Set the angular position of servo ID 2 to 900 for the extended state with a running time of 2,000 ms.</p></li><li><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p></p><p><strong>Setting the running time to 2,000 ms, equivalent to 2 s, makes the forward and backward motion of the robotic arm easier to observe. Limiting the angular position of servo ID 2 between a minimum of 100 and a maximum of 900 protects the servo from mechanical damage caused by extreme angles.</strong></p></div></li></ul><img loading="lazy" height="172" width="562" src="'+m+'" class="common_img" style="width:600px;aspect-ratio:562 / 172;"><p><strong>Task 2: Setting the Angular Position of Bus Servo ID 3 for Robotic Arm Lifting and Lowering</strong></p><ul><li><p>Building upon Task 1, add control blocks for servo ID 3.</p></li><li><p>When the A key is pressed, set the angular position of servo ID 3 to lower the robotic arm with a running time of 2,000 ms.</p></li><li><p>Wait 5 s.</p></li><li><p>Set the angular position of servo ID 3 to raise the robotic arm with a running time of 2,000 ms.</p></li><li><p>Setting bus servos ID 1, ID 2, and ID 3 to an angular position of 500 places them at their initial angles, where the gripper is closed and the robotic arm controlled by servo ID 2 and servo ID 3 stands in a vertical posture.</p></li></ul><img loading="lazy" height="169" width="568" src="'+u+'" class="common_img" style="width:600px;aspect-ratio:568 / 169;"><p><strong>Task 3: Cycling the Robotic Arm Between Low and High Angles</strong></p><ul><li><p>Combine bus servo ID 2 and bus servo ID 3 by setting their angular positions simultaneously to achieve coordinated low-to-high movement of the robotic arm.</p></li><li><p>Low-angle state: Set servo ID 2 to a smaller angle for retraction and servo ID 3 to a smaller angle for lowering.</p></li><li><p>High-angle state: Set servo ID 2 to a larger angle for extension and servo ID 3 to a larger angle for lifting.</p></li><li><p>Add a repeat-forever loop structure so that pressing the A key drives the robotic arm to cycle continuously from low to high and back from high to low.</p></li><li><p>Set the robotic arm to the low-angle posture at startup as the default power-on angle.</p></li></ul><img loading="lazy" height="499" width="576" src="'+f+'" class="common_img" style="width:600px;aspect-ratio:576 / 499;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Orientation Navigation Challenge</a>.</strong></p></div><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-13-5-expansion-and-advancement" tabindex="-1">3.13.5 Expansion and Advancement <a class="header-anchor" href="#_3-13-5-expansion-and-advancement" aria-label="Permalink to &quot;3.13.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Three-Stage Lifting Transition with Sound and Light Feedback</strong></p><p>Optimize the robotic arm trajectory based on the basic lifting program to achieve a smooth three-stage transition across low, middle, and high positions. Introduce the RGB LEDs and buzzer for corresponding state feedback, precisely calibrating the angle parameters and matching the operating intervals so that the sound and light effects synchronize strictly with the arm movements.</p><p><strong>Project 2: Real-Time Robotic Arm Angular Position Readback and Limit Protection</strong></p><p>Write a program to read the angles of servo ID 2 and servo ID 3 in real time and print the values via the serial port. Configure limit protection so that when the angle of servo ID 2 is less than 100 or greater than 900, or when servo ID 3 exceeds its limits, the robotic arm automatically stops and illuminates a red warning light. Implement closed-loop control through continuous loop monitoring and conditional evaluation to reinforce the concepts of feedback mechanisms and robot safety control.</p><h2 id="_3-13-6-q-a" tabindex="-1">3.13.6 Q&amp;A <a class="header-anchor" href="#_3-13-6-q-a" aria-label="Permalink to &quot;3.13.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What advantages do bus servos have compared to traditional analog servos or digital servos?</strong></p><p><strong>Answer</strong>: Bus servos support bidirectional communication and can feed back status data such as position and temperature to achieve precise closed-loop control. Compared to traditional analog servos, bus servos transmit commands via serial protocols and allow multiple servos to be daisy-chained in series, simplifying wiring and facilitating expansion. Their high intelligence and programmability make them an ideal choice for building multi-degree-of-freedom robotic arms.</p><p><strong>Q2: What components make up the robotic arm structure, and what movements do the three bus servos control respectively?</strong></p><p><strong>Answer</strong>: The robotic arm consists of a base, an arm linkage, and an end effector. Servo ID 1 controls the opening and closing of the gripper, servo ID 2 controls horizontal extension and retraction, and servo ID 3 controls vertical lifting and lowering. The three servos work in coordination to achieve three-dimensional spatial positioning and grasping. In the initial state, the angular position of each servo is set to 500, keeping the gripper closed and the arm linkage vertical.</p><h2 id="_3-13-7-technical-support-and-discussion" tabindex="-1">3.13.7 Technical Support and Discussion <a class="header-anchor" href="#_3-13-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.13.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',44)])])}const C=i(b,[["render",v]]);export{A as __pageData,C as default};
